export{ModalWhatsAppCtrl};function ModalWhatsAppCtrl(e,s,t,i,o){e.client={},e.client.id=o.codEstab,e.client.description=o.description?o.description:"Session de Whatsapp del estab: "+o.codEstab,e.sessions=[],e.whatsapp={number:"0991229095"},e.login=()=>{i.emit("create-session",{id:e.client.id,description:e.client.description})},i.on("init",(s=>{for(const i of s)e.client.id==i.id&&e.sessions.push({id:i.id,description:i.description}),i.ready?(e.client.isLogged=!0,t.toastr("success","Whatsapp esta listo")):t.toastr("info","Conectando con el servicio de Whatsapp ...")})),i.on("remove-session",(s=>{e.client.id==s&&(e.client.isLogged=!1)})),i.on("message",(e=>{t.toastr("info",e.text,"Estado")})),i.on("qr",(s=>{e.client.id==s.id&&(e.sessions.push({id:s.id,description:s.description}),$(`#${s.id}-qrcode`).attr("src",s.src))})),i.on("ready",(e=>{})),e.sendMessage=()=>{try{showLoader();let s={number:e.whatsapp.number,message:e.whatsapp.message,sender:e.client.id};$http.post("http://localhost:8000/send-message",s).then((e=>{hideLoader()})).catch((e=>{hideLoader()}))}catch(e){hideLoader()}},e.closeModal=function(){s.close()}}ModalWhatsAppCtrl.$inject=["$scope","$uibModalInstance","toastService","socketService","params"];